    const height = (id: number): number =>
      1 + Math.max(0, ...[...parents].filter(([, parent]) => parent === id).map(([child]) => height(child)));
    if (depth + height(memberId) > MAX_DEPTH) return 'A chain of pools is at most three deep.';
